import { ReactNode, FC } from 'react';

interface BottomSheetProps {
    /** 是否显示 */
    open: boolean;
    /** 标题 */
    title?: ReactNode;
    /** 描述 */
    description?: ReactNode;
    /** 关闭回调 */
    onClose?: () => void;
    /** 是否显示拖拽条 */
    showHandle?: boolean;
    /** 是否显示关闭按钮 */
    closable?: boolean;
    /** 点击遮罩是否关闭 */
    closeOnOverlayClick?: boolean;
    /** 高度模式：'auto' 自适应 | 'full' 全屏 | number (rpx 数值) */
    height?: 'auto' | 'full' | number;
    /** 是否启用拖拽关闭 (Phase 2) */
    draggable?: boolean;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

declare const BottomSheet: FC<BottomSheetProps>;

export { BottomSheet, BottomSheet as default };
export type { BottomSheetProps };
